from decimal import Decimal, ROUND_HALF_UP, InvalidOperation
import math


def invoice_total(lines, discount_percent="0"):
    if not isinstance(lines, list):
        raise ValueError("lines must be a list")

    try:
        discount = Decimal(str(discount_percent))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError("invalid discount_percent")

    if not math.isfinite(float(discount)):
        raise ValueError("discount_percent must be finite")
    if discount < 0 or discount > 100:
        raise ValueError("discount_percent must be between 0 and 100")

    total_net = Decimal("0")
    total_tax = Decimal("0")

    for line in lines:
        if not isinstance(line, dict):
            raise ValueError("each line must be a dictionary")

        for field in ("quantity", "unit_price", "vat_percent"):
            if field not in line:
                raise ValueError(f"missing field: {field}")

        try:
            quantity = Decimal(str(line["quantity"]))
            unit_price = Decimal(str(line["unit_price"]))
            vat_percent = Decimal(str(line["vat_percent"]))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError("invalid decimal value")

        for val, name in ((quantity, "quantity"), (unit_price, "unit_price"), (vat_percent, "vat_percent")):
            if not math.isfinite(float(val)):
                raise ValueError(f"{name} must be finite")
            if val < 0:
                raise ValueError(f"{name} must be non-negative")

        gross = quantity * unit_price
        net = gross * (Decimal("1") - discount / Decimal("100"))
        net = net.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        tax = net * (vat_percent / Decimal("100"))
        tax = tax.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        total_net += net
        total_tax += tax

    total = total_net + total_tax

    return {
        "net": str(total_net.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)),
        "tax": str(total_tax.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)),
        "total": str(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)),
    }
