def order_tasks(tasks):
    if not tasks:
        return []

    # Validate and build structures
    seen_ids = set()
    task_order = []  # original order of ids
    deps = {}  # id -> set of dependency ids

    for task in tasks:
        tid = task["id"]
        if tid in seen_ids:
            raise ValueError(f"Duplicate task id: {tid}")
        seen_ids.add(tid)
        task_order.append(tid)

        dep_list = task.get("depends_on", [])
        dep_set = set()
        for d in dep_list:
            if d == tid:
                raise ValueError(f"Self dependency on task: {tid}")
            dep_set.add(d)
        deps[tid] = dep_set

    # Validate all dependencies are known
    for tid in task_order:
        for d in deps[tid]:
            if d not in seen_ids:
                raise ValueError(f"Unknown dependency: {d}")

    # Build in-degree map and adjacency (dependents)
    in_degree = {tid: 0 for tid in task_order}
    dependents = {tid: [] for tid in task_order}  # tid -> list of tasks that depend on tid

    for tid in task_order:
        for d in deps[tid]:
            in_degree[tid] += 1
            dependents[d].append(tid)

    # Ready queue: tasks with in_degree 0, ordered by original input order
    # We need to pick the ready task that appeared earliest in the original input.
    # Use a list of ready tasks and always pick the one with the smallest original index.
    # To do this efficiently, we can maintain a list and scan, but for 2000 tasks that's fine.
    # Alternatively, use a heap keyed by original index.

    import heapq

    # Map id -> original index
    original_index = {tid: i for i, tid in enumerate(task_order)}

    # Initialize heap with all tasks that have in_degree 0
    heap = []
    for tid in task_order:
        if in_degree[tid] == 0:
            heapq.heappush(heap, (original_index[tid], tid))

    result = []
    processed = 0

    while heap:
        _, tid = heapq.heappop(heap)
        result.append(tid)
        processed += 1

        for dependent in dependents[tid]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, (original_index[dependent], dependent))

    if processed != len(task_order):
        raise ValueError("Cycle detected in task dependencies")

    return result
