'use strict';

function createAsyncCache(load, ttlMs, now = Date.now) {
  const cache = new Map(); // key -> { value, expiresAt }
  const inFlight = new Map(); // key -> { promise, token }

  function get(key) {
    const current = now();

    // Check cache
    const entry = cache.get(key);
    if (entry !== undefined) {
      if (current < entry.expiresAt) {
        return Promise.resolve(entry.value);
      } else {
        // Expired, remove it
        cache.delete(key);
      }
    }

    // Check in-flight
    const inflight = inFlight.get(key);
    if (inflight !== undefined) {
      return inflight.promise;
    }

    // Start a new load
    let resolvePromise;
    let rejectPromise;
    const promise = new Promise((resolve, reject) => {
      resolvePromise = resolve;
      rejectPromise = reject;
    });

    const token = {};
    inFlight.set(key, { promise, token });

    let result;
    try {
      result = load(key);
    } catch (err) {
      // Synchronous throw: clean up in-flight, reject
      inFlight.delete(key);
      rejectPromise(err);
      return promise;
    }

    Promise.resolve(result).then(
      (value) => {
        // Only update cache if this is still the current in-flight for this key
        const currentInflight = inFlight.get(key);
        if (currentInflight !== undefined && currentInflight.token === token) {
          inFlight.delete(key);
          const expiresAt = now() + ttlMs;
          cache.set(key, { value, expiresAt });
        }
        resolvePromise(value);
      },
      (err) => {
        // Rejections are not cached; clean up in-flight if still current
        const currentInflight = inFlight.get(key);
        if (currentInflight !== undefined && currentInflight.token === token) {
          inFlight.delete(key);
        }
        rejectPromise(err);
      }
    );

    return promise;
  }

  function invalidate(key) {
    cache.delete(key);
    inFlight.delete(key);
  }

  return { get, invalidate };
}

module.exports = { createAsyncCache };
